import numpy as np, pandas as pd
from scipy.optimize import minimize
import os

WS = r"<workspace>"
df = pd.read_parquet(os.path.join(WS, "equation.parquet"))
data = df.iloc[0]['training_set'].tolist()
out = np.array([r[0] for r in data])
X = np.array([r[1:] for r in data])
t, A = X.T


def fit(fn, nparams=10, seed=None):
    rng = np.random.default_rng(0)
    best = None
    starts = [[1.0]*nparams]
    for _ in range(0):
        starts.append(list(rng.normal(0, 0.5, nparams)))
    for s in starts:
        r = minimize(lambda p: np.mean((fn(t, A, p) - out)**2), s, method='BFGS',
                     options={'maxiter': 2000, 'gtol': 1e-10})
        if best is None or r.fun < best.fun:
            best = r
    return best.fun, best.x


def base3(t, A, p):
    return p[0]*t + p[1]*A + p[2]


def sat(t, A, p):
    return p[3]*A/(1+np.abs(p[4])*A)


def dexp(t, A, p):
    return p[5]*np.exp(-np.abs(p[6])*t)


def tA2(t, A, p):
    return p[7]*t*A**2


def current(t, A, p):
    return base3(t, A, p) + sat(t, A, p) + dexp(t, A, p) + tA2(t, A, p)


def rat_tA(t, A, p):
    # k * t*A/(1+|p|*t)
    return p[8]*t*A/(1+np.abs(p[9])*t)


def logistic(t, A, p):
    return p[8]*A/(1+np.exp(-np.abs(p[9])*t))


def expA2(t, A, p):
    return p[8]*np.exp(-np.abs(p[9])*t)*A**2


cands = {
    "current": current,
    "current+rat_tA": lambda t, A, p: current(t, A, p) + rat_tA(t, A, p),
    "current+expA2": lambda t, A, p: current(t, A, p) + expA2(t, A, p),
    "current+logistic": lambda t, A, p: current(t, A, p) + logistic(t, A, p),
    "base+rat_tA": lambda t, A, p: base3(t, A, p) + rat_tA(t, A, p) + tA2(t, A, p),
    "base+expA2": lambda t, A, p: base3(t, A, p) + dexp(t, A, p) + expA2(t, A, p),
}

for name, fn in cands.items():
    loss, p = fit(fn)
    print(f"{name:20s} MSE={loss:.6e}")
